// ── Settings: change these in n8n, no server restart needed ──────────────────
const SEND_ALERT = false;                                   // true once the "Resend API key" credential is set on "Send alert (Resend)"
const ALERT_EMAIL = 'you@example.com';                      // where failure alerts go (Resend's test sender only delivers to your Resend sign-up email)
const EMAIL_FROM = 'Demo Academy <onboarding@resend.dev>';
// ─────────────────────────────────────────────────────────────────────────────
const e = $input.first().json;
const failedNode = e.execution?.lastNodeExecuted || 'unknown node';
const message = e.execution?.error?.message || 'unknown error';
const lines = [
  `Workflow: ${e.workflow?.name}`,
  `Node: ${failedNode}`,
  `Error: ${message}`,
  `Execution: ${e.execution?.url || ''}`,
];
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
return [{
  json: {
    mode: SEND_ALERT ? 'resend' : 'dry_run',
    request: {
      from: EMAIL_FROM,
      to: [ALERT_EMAIL],
      subject: `[Academy] Workflow failed at "${failedNode}"`,
      text: lines.join('\n'),
      html: `<p>${lines.map(esc).join('<br>')}</p>`,
    },
  },
}];
